const ROOT=self.registration.scope;
const PREFIX='tesla-jump:'+new URL(ROOT).pathname+':';
const CACHE=PREFIX+VERSION;

self.addEventListener('install',event=>event.waitUntil((async()=>{
 const cache=await caches.open(CACHE);
 const results=await Promise.allSettled(CORE.map(async item=>{
  const response=await fetch(new Request(new URL(item.url,ROOT),{cache:'reload'}));
  if(!response.ok)throw Error('Incomplete offline content');
  const digest=await crypto.subtle.digest('SHA-256',await response.clone().arrayBuffer());
  const hash=Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');
  if(hash!==item.sha256)throw Error('Offline content version mismatch');
  await cache.put(new URL(item.url,ROOT).href,response);
 }));
 if(results.some(r=>r.status==='rejected')){await caches.delete(CACHE);throw Error('Offline installation incomplete');}
 // No skipWaiting here: an unfinished run must retain its current release.
})()));

self.addEventListener('activate',event=>event.waitUntil((async()=>{
 const previous=(await caches.keys()).filter(name=>name.startsWith(PREFIX)&&name!==CACHE);
 for(const name of previous.slice(0,-1))await caches.delete(name);
 await self.clients.claim();
 const clients=await self.clients.matchAll({type:'window'});
 for(const client of clients)client.postMessage({type:'OFFLINE_READY',version:VERSION});
})()));

self.addEventListener('message',event=>{
 if(event.data?.type!=='APPLY_UPDATE')return;
 event.waitUntil((async()=>{
  const clients=(await self.clients.matchAll({type:'window',includeUncontrolled:true})).filter(client=>client.url.startsWith(ROOT));
  if(event.data.safe!==true||clients.length!==1||clients[0].id!==event.source?.id){event.source?.postMessage({type:'UPDATE_BLOCKED'});return;}
  // The requesting menu/result is locked until controllerchange. Other open
  // windows block activation instead of risking a running game in another tab.
  await self.skipWaiting();
 })());
});

self.addEventListener('fetch',event=>{
 const request=event.request,url=new URL(request.url),base=new URL(ROOT);
 if(request.method!=='GET'||url.origin!==base.origin||!url.href.startsWith(ROOT))return;
 const appNavigation=request.mode==='navigate'&&(url.pathname===base.pathname||url.pathname===base.pathname+'index.html');
 event.respondWith((async()=>{
  const cache=await caches.open(CACHE);
  // Navigation uses a coherent cached shell. Update discovery/activation is a
  // separate operation; a newer network HTML must not consume old cached art.
  const cached=await cache.match(appNavigation?new URL('index.html',ROOT).href:request);
  return cached||fetch(request);
 })());
});
